import sys

def get_weight_category(weight):
    if weight > 50:
        return "Overweight"
    elif weight > 20:
        return "Heavy"
    elif weight > 5:
        return "Standard"
    elif weight > 0:
        return "Lightweight"
    else:
        return "Invalid"

def calculate_cost(category, distance, shipment_type):
    if category == "Lightweight":
        rate = 1.00 if shipment_type == "domestic" else 2.00
    elif category == "Standard":
        rate = 1.50 if shipment_type == "domestic" else 3.00
    elif category == "Heavy":
        rate = 2.00 if shipment_type == "domestic" else 4.00
    elif category == "Overweight":
        rate = 3.00 if shipment_type == "domestic" else 6.00
    else:
        rate = 0.00

    return distance * rate

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    index = 1

    results = []
    for _ in range(n):
        weight = float(data[index])
        distance = int(data[index + 1])
        shipment_type = data[index + 2]
        index += 3

        category = get_weight_category(weight)
        cost = calculate_cost(category, distance, shipment_type)

        results.append(category)
        results.append(shipment_type)
        results.append("{:.2f}".format(cost))

    print("\n".join(results))

if __name__ == "__main__":
    main()
